list_categories.code:
var response = await client.Categories.ListCategoriesAsync(new Dictionary<string, object?>
{
    ["limit"] = 10, ["offset"] = 10, ["sort"] = "name", ["dir"] = "asc",
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var category in ((IReadOnlyList<object?>)body["categories"]!).Cast<IReadOnlyDictionary<string, object?>>())
{
    var general = (IReadOnlyDictionary<string, object?>)category["general"]!;
    Console.WriteLine($"{category["id"]} {general["name"]}");
}

