patch_category_section.code:
var response = await client.Categories.PatchCategorySectionAsync(4321, "assign_products", new Dictionary<string, object?>
{
    ["category"] = new Dictionary<string, object?>
    {
        ["assign_products"] = new Dictionary<string, object?> { ["products"] = new List<object?> { 101, 102, 103 } },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var category = (IReadOnlyDictionary<string, object?>)body["category"]!;
var assignProducts = (IReadOnlyDictionary<string, object?>)category["assign_products"]!;
foreach (var product in ((IReadOnlyList<object?>)assignProducts["products"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{product["id"]} {product["sku"]}");
